CREATE DATABASE IF NOT EXISTS househunt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE househunt;
CREATE TABLE users(user_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone_number VARCHAR(30) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('landlord','tenant') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE properties(property_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,landlord_id INT UNSIGNED NOT NULL,property_title VARCHAR(150) NOT NULL,description TEXT NOT NULL,county VARCHAR(100) NOT NULL,town VARCHAR(100) NOT NULL,neighbourhood VARCHAR(120) NOT NULL,property_type VARCHAR(80) NOT NULL,bedrooms TINYINT UNSIGNED NOT NULL DEFAULT 0,bathrooms TINYINT UNSIGNED NOT NULL DEFAULT 0,monthly_rent DECIMAL(12,2) NOT NULL,deposit DECIMAL(12,2) NULL,availability_status ENUM('Available','Occupied') NOT NULL DEFAULT 'Available',availability_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(landlord_id) REFERENCES users(user_id) ON DELETE CASCADE,INDEX(availability_status,town,property_type,monthly_rent)) ENGINE=InnoDB;
CREATE TABLE property_images(image_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,image_url VARCHAR(255) NOT NULL,FOREIGN KEY(property_id) REFERENCES properties(property_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE amenities(amenity_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,amenity_name VARCHAR(80) UNIQUE NOT NULL) ENGINE=InnoDB;
CREATE TABLE property_amenities(property_id INT UNSIGNED NOT NULL,amenity_id INT UNSIGNED NOT NULL,PRIMARY KEY(property_id,amenity_id),FOREIGN KEY(property_id) REFERENCES properties(property_id) ON DELETE CASCADE,FOREIGN KEY(amenity_id) REFERENCES amenities(amenity_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE favourites(favourite_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id INT UNSIGNED NOT NULL,property_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(tenant_id,property_id),FOREIGN KEY(tenant_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(property_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE enquiries(enquiry_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id INT UNSIGNED NOT NULL,property_id INT UNSIGNED NOT NULL,message TEXT NOT NULL,enquiry_status ENUM('Sent','Responded','Closed') DEFAULT 'Sent',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(property_id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT IGNORE INTO amenities(amenity_name) VALUES('Parking'),('Wi-Fi'),('Reliable water supply'),('Swimming pool'),('Security'),('CCTV'),('Balcony'),('Garden'),('Borehole'),('Backup generator'),('Electricity'),('Furnished'),('Pet-friendly'),('Near public transport');
